CREATE TABLE `ultary_ai_moderation_job` (
  `job_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `target_type` varchar(10) NOT NULL,
  `target_id` int(11) NOT NULL,
  `feed_id` int(11) NOT NULL,
  `user_no` int(11) NOT NULL,
  `content_version` bigint(20) NOT NULL,
  `operation` varchar(10) NOT NULL,
  `content` varchar(500) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PENDING',
  `attempt_count` int(11) NOT NULL DEFAULT '0',
  `next_attempt_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lease_until` datetime DEFAULT NULL,
  `claim_token` varchar(36) DEFAULT NULL,
  `last_error_code` varchar(100) DEFAULT NULL,
  `last_error` varchar(1000) DEFAULT NULL,
  `result_action` varchar(20) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `finished_at` datetime DEFAULT NULL,
  `admin_review_status` varchar(10) NOT NULL DEFAULT 'PENDING',
  `admin_reviewed_at` datetime DEFAULT NULL,
  `admin_reviewed_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`job_id`),
  UNIQUE KEY `UK_ai_moderation_version` (`target_type`,`target_id`,`content_version`),
  KEY `IDX_ai_moderation_poll` (`status`,`next_attempt_at`,`lease_until`),
  KEY `IDX_ai_moderation_user` (`user_no`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=1386 DEFAULT CHARSET=utf8mb4;
