INSERT INTO `ultary_ai_moderation_job` VALUES (71,'COMMENT',815,103,101,1,'UPDATE','오늘 산책 나갔어요? 씨발 놈아123','SKIPPED',3,'2026-10-20 11:29:05',NULL,NULL,'GEMINI_TIMEOUT','Response deadline exceeded (8000ms)','HIDDEN','2026-10-20 11:27:30','2026-10-25 23:06:40','DELETED','2026-10-25 23:06:40',1),(105,'REPLY',676,118,101,1,'CREATE','@산책러 씨발','REJECTED',1,'2026-10-20 14:37:52',NULL,NULL,NULL,NULL,'HIDDEN','2026-10-20 14:37:50','2026-10-20 14:37:52','PENDING',NULL,NULL),(106,'COMMENT',1024,118,101,1,'CREATE','병신','REJECTED',1,'2026-10-20 14:46:18',NULL,NULL,NULL,NULL,'HIDDEN','2026-10-20 14:46:13','2026-10-20 14:46:18','PENDING',NULL,NULL),(763,'REPLY',970,122,101,1,'CREATE','@구경꾼 안녕 @아니그냥가','APPROVED',1,'2026-10-27 17:21:36',NULL,NULL,NULL,NULL,NULL,'2026-10-27 17:21:33','2026-10-27 17:21:36','PENDING',NULL,NULL),(764,'COMMENT',1600,122,101,1,'CREATE','@나리집사','APPROVED',1,'2026-10-27 17:29:02',NULL,NULL,NULL,NULL,NULL,'2026-10-27 17:29:00','2026-10-27 17:29:02','PENDING',NULL,NULL),(1379,'COMMENT',2373,2762,101,1,'CREATE','댓글 테스트','APPROVED',1,'2026-11-03 15:17:04',NULL,NULL,NULL,NULL,NULL,'2026-11-03 15:17:02','2026-11-03 15:17:04','PENDING',NULL,NULL),(1380,'COMMENT',2374,2762,101,1,'CREATE','테스트 댓글!!','APPROVED',1,'2026-11-03 15:27:41',NULL,NULL,NULL,NULL,NULL,'2026-11-03 15:27:38','2026-11-03 15:27:41','PENDING',NULL,NULL),(1381,'COMMENT',2375,2762,101,1,'CREATE','안\n녕\n하\n세\n요','APPROVED',1,'2026-11-03 15:27:49',NULL,NULL,NULL,NULL,NULL,'2026-11-03 15:27:46','2026-11-03 15:27:49','PENDING',NULL,NULL),(1382,'COMMENT',2376,2762,101,1,'CREATE','안녕하세요\n감사해요\n잘있어요\n다시만나요\n안녕하세요\n감사해요\n잘있어요\n다시만나요','APPROVED',1,'2026-11-03 15:33:31',NULL,NULL,NULL,NULL,NULL,'2026-11-03 15:33:28','2026-11-03 15:33:31','PENDING',NULL,NULL),(1383,'COMMENT',2376,2762,101,2,'UPDATE','안녕하세요\n감사해요\n잘있어요\n다시만나요\n안녕하세요\n감사해요\n잘있어요\n다시만나요!!!!','APPROVED',1,'2026-11-03 15:37:30',NULL,NULL,NULL,NULL,NULL,'2026-11-03 15:37:27','2026-11-03 15:37:30','PENDING',NULL,NULL);
