CREATE TABLE `ultary_ai_moderation_state` (
  `target_type` varchar(10) NOT NULL,
  `target_id` int(11) NOT NULL,
  `latest_version` bigint(20) NOT NULL DEFAULT '0',
  `approved_version` bigint(20) NOT NULL DEFAULT '0',
  `approved_content` varchar(500) DEFAULT NULL,
  `has_approved` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`target_type`,`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
