INSERT INTO `ultary_ai_moderation_state` VALUES ('COMMENT',815,1,1,'오늘 산책 나갔어요? 씨발 놈아123',1),('COMMENT',1024,2,0,NULL,0),('COMMENT',1600,1,1,'@nari_owner',1),('COMMENT',2373,1,1,'댓글 테스트',1),('COMMENT',2374,1,1,'테스트 댓글!!',1),('COMMENT',2375,1,1,'안\n녕\n하\n세\n요',1),('COMMENT',2376,2,2,'안녕하세요\n감사해요\n잘있어요\n다시만나요\n안녕하세요\n감사해요\n잘있어요\n다시만나요!!!!',1),('FEED',101,2,2,'코코와 초록 잔디를 걸었어요. 새로운 냄새가 가득한 오늘의 산책.. #산책 #강아지산책',1),('FEED',102,1,1,'호두의 커다란 하품! 잠에서 막 깬 표정도 귀여워서 남겨요. #고양이 #휴식 #귀여움 #힐링 #하품',1),('FEED',103,1,1,'구름이와 집에서 보내는 포근한 하루. 폭신한 담요 위가 제일 좋은가 봐요. #집콕 #휴식 #말티즈 #힐링',1),('FEED',105,3,3,'코코와 레오가 함께한 피크닉. 잔디 위에 나란히 앉아 쉬어 가는 우리 집 두 친구. #피크닉 #강아지산책 #산책코스 #주말산책 #나들이',1),('FEED',107,1,1,'보리의 웃는 얼굴을 담았어요. 햇살 좋은 날의 기분 좋은 산책. #피크닉 #산책 #펫스타그램 #반려견 #반려견일상',1),('FEED',110,2,2,'마루와 호두가 나란히 앉았어요. 함께 보내는 오후가 더 즐거워요. #견생샷 #반려인소통 #합사 #친구',1),('FEED',111,1,1,'노을빛 산책길에서 만난 마루의 환한 표정. 내일도 같이 걷자. #강아지산책 #저녁산책 #시바견',1),('FEED',114,1,1,'몽이와 반려동물 동반 카페에 들렀어요. 보호자 간식 옆에서 얌전히 기다리는 중! #펫카페 #강아지동반 #반려동물동반카페',1),('FEED',118,4,4,'창가 소파에서 느긋하게 쉬는 레오. 부드러운 담요와 햇살이면 충분해요. #고양이 #펫스타그램 #펫쿠션',1),('FEED',122,1,1,'모카의 창가 자리에서 시작하는 느긋한 오후. 햇살을 실컷 즐겼어요. #고양이 #일상기록',1),('FEED',143,1,1,'가벼운 발걸음으로 동네를 걷는 마루. 익숙한 길도 매일 새로워요. #산책 #일상기록 #시바견 #시바이누 #산책길 #동네산책 #강아지산책',1),('FEED',149,1,1,'별이의 신나는 집 안 탐험. 작은 장난감 하나에도 눈이 반짝여요. #반려묘 #실내놀이 #고양이 #집사일상',1),('FEED',152,1,1,'담요 속에 쏙 들어간 단추. 오늘은 집에서 푹 쉬는 날이에요. #휴식 #힐링 #집콕 #강아지 #일상기록',1),('FEED',2748,1,1,'꽃 옆에서 조용히 구경하는 까망이. 호기심 가득한 눈빛을 담았어요. #코숏 #반려묘 #일상기록 #고양이 #검은고양이',1),('FEED',2749,1,1,'초코가 아끼는 인형과 보내는 오후. 같이 뒹굴다 보니 시간이 훌쩍 갔네요. #닥스훈트 #강아지일상 #뒹굴뒹굴 #애착인형',1),('FEED',2750,1,1,'밤비와 집에서 장난감 놀이. 편안한 옷을 입고 느긋하게 쉬는 중이에요. #휴식 #닥스훈트 #실내놀이 #멍스타그램',1),('FEED',2751,1,1,'햇살 드는 소파에서 잠든 치즈. 조용한 낮잠 시간을 살짝 기록해요. #코숏 #고양이 #일상기록 #힐링 #휴식',1),('FEED',2752,1,1,'낙엽 사이를 킁킁 살피는 쿠키. 가을 산책에는 구경할 게 참 많아요. #나들이 #킁킁 #산책 #강아지산책 #비글',1),('FEED',2756,1,1,'마루의 식사 자리에 새 식기를 놓았어요. 밥과 물을 나란히 준비하니 한결 깔끔해졌네요. #원목식기 #시바견 #강아지식사 #강아지용품 #시바이누',1),('FEED',2757,1,1,'쿠키의 밥 먹는 시간. 식사 공간을 한곳에 정리하고 오늘도 천천히 맛있게 먹어요. #원목식기 #반려견 #반려동물 #강아지용품 #강아지식기 #먹방',1),('FEED',2759,1,1,'밤비와 집에서 보내는 놀이 시간. 물고 당기며 놀다 보니 지루할 틈이 없네요. #강아지장난감 #놀이 #터그놀이 #반려견 #펫토이',1),('FEED',2760,1,1,'별이가 새 장난감을 탐색하는 중이에요. 강아지용 장난감에도 호기심을 보이네요. 옆에서 지켜보며 잠깐 놀았어요. #강아지장난감 #고양이 #놀이 #반려묘 #펫토이',1),('FEED',2761,1,1,'까망이와 함께하는 짧은 빗질 시간. 편안해하는 만큼만 조금씩 털을 정돈했어요. #펫브러시 #빗질 #털관리 #털갈이 #털정리',1),('FEED',2762,1,1,'치즈의 오늘 그루밍 기록. 느긋하게 쉬는 동안 살살 빗겨 주니 포근한 털이 한결 가지런해졌어요. #펫브러시 #그루밍 #털관리',1),('FEED',2763,1,1,'초코의 일상용품을 모아봤어요. 식사 자리에는 새 식기를, 목욕 준비에는 샴푸를 챙겼습니다. #강아지식기 #펫샴푸 #펫용품 #목욕 #강아지용품',1),('FEED',2764,1,1,'마루와 모카가 함께한 하루. 식사와 산책 준비를 하며 두 친구의 모습을 한 장에 담았어요. #원목식기 #산책하네스 #반려동물 #산책준비',1),('FEED',3707,2,2,'우리 집 삼총사 소개 🐾\n\n햇살 좋아하는 코코,\n카페만 가면 신나는 몽이,\n창가 자리가 제일 좋은 레오.\n\n좋아하는 것도 성격도 다 다르지만\n함께라서 더 즐거운 우리 집 일상 🤍\n\n#코코 #몽이 #레오 #반려동물 #멍스타그램 #냥스타그램 #펫스타그램 #울타리',1),('FEED',3708,2,2,'둘이 붙어 있으면 케미가 두 배 🐶🐱\n\n코코와 레오는 여유로운 피크닉 친구,\n코코와 몽이는 어디서든 신나는 산책 친구!\n\n조합마다 분위기는 달라도\n같이 있는 순간은 언제나 귀엽다 🌿\n\n#반려동물친구 #코코 #몽이 #레오 #강아지와고양이 #펫일상 #산책스타그램 #울타리',1),('FEED',3709,2,2,'결국 셋이 다 모여야 우리 집 완전체 🐾\n\n몽이랑 레오의 포근한 오후부터\n코코까지 합류한 호숫가 피크닉,\n집에서 나란히 쉬는 순간까지.\n\n특별한 일이 없어도\n함께 있으면 그게 제일 좋은 하루 ☀️\n\n#우리집삼총사 #코코 #몽이 #레오 #반려동물일상 #댕냥이 #펫라이프 #일상기록 #울타리',1),('FEED',3722,1,1,'코코랑 까망이, 처음엔 어색하더니 어느새 이렇게 붙어있기 🐶🐱 햇살 좋은 날엔 같이 늘어지는 게 최고!\n\n#코코 #까망이 #댕냥친구 #반려동물일상 #펫스타그램 #울타리',1),('FEED',3723,1,1,'몽이랑 보리랑 호숫가 피크닉 🌼 간식도 먹고 바람도 쐬고, 신나게 놀다 온 하루!\n\n#몽이 #보리 #강아지친구 #피크닉 #산책일상 #멍스타그램 #울타리',1),('FEED',3724,1,1,'오늘은 레오랑 단추의 휴식 시간. 나란히 누워있는 모습이 생각보다 너무 잘 어울린다 🤎\n\n#레오 #단추 #댕냥이 #포근한하루 #반려동물 #일상기록 #울타리',1),('FEED',3725,3,3,'산책하다 만난 보리까지 합류! 마루랑 별이도 오늘 새로운 친구가 생겼어요 🌿🐾\n\n#마루 #별이 #보리 #반려동물친구 #산책 #펫일상 #울타리',1),('FEED',3726,1,1,'햇살 좋은 창가에서 만난 까망이와 구름 ☀️ 성격은 달라도 같이 있으면 제법 평화로운 조합.\n\n#까망이 #구름 #댕냥친구 #햇살맛집 #반려동물일상 #울타리',1),('FEED',3727,3,3,'보리 친구들 놀러 온 날! 모카랑 단추까지 모이니 집이 금세 북적북적 🐾 그래도 이런 북적임은 언제든 환영!\n\n#보리 #모카 #단추 #우리집놀이터 #반려동물친구 #펫라이프 #울타리',1),('FEED',3728,1,1,'별이랑 호두의 카페 나들이에 코코도 합류 ☕🐾 셋이 같이 있으니 사진 한 장도 그냥 지나칠 수가 없다.\n\n#코코 #별이 #호두 #펫카페 #댕냥이 #친구스타그램 #울타리',1),('FEED',3729,1,1,'몽이, 구름, 모카랑 꽃구경 🌸 날씨도 좋고 친구들도 함께라 더 기분 좋은 하루!\n\n#몽이 #구름 #모카 #꽃구경 #반려동물친구 #펫일상 #울타리',1),('REPLY',676,2,0,NULL,0),('REPLY',970,1,1,'@visitor 안녕 @아니그냥가',1);
/*!40000 ALTER TABLE `ultary_ai_moderation_state` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `ultary_ai_request_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_ai_request_log` (
  `ai_request_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_no` int(11) NOT NULL,
  `feature_type` enum('FEED_CAPTION','HASHTAG','PET_PROFILE','COMMENT_FILTER','ALT_TEXT') NOT NULL,
  `target_feed_id` int(11) DEFAULT NULL,
  `target_pet_id` int(11) DEFAULT NULL,
  `prompt` varchar(1000) DEFAULT NULL,
  `result` varchar(2000) DEFAULT NULL,
  `model_name` varchar(100) DEFAULT NULL,
  `used_token_count` int(11) DEFAULT NULL,
  `status` enum('PENDING','SUCCESS','FAILED') NOT NULL DEFAULT 'PENDING',
  `error_message` varchar(1000) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `moderation_job_id` bigint(20) DEFAULT NULL,
  `target_type` varchar(10) DEFAULT NULL,
  `target_id` int(11) DEFAULT NULL,
  `content_version` bigint(20) DEFAULT NULL,
  `attempt_no` int(11) DEFAULT NULL,
  `latency_ms` bigint(20) DEFAULT NULL,
  `http_status` int(11) DEFAULT NULL,
  `error_code` varchar(100) DEFAULT NULL,
  `inspection_content` mediumtext,
  PRIMARY KEY (`ai_request_id`) USING BTREE,
  KEY `IDX_ultary_ai_user_created` (`user_no`,`created_at`) USING BTREE,
  KEY `IDX_ultary_ai_target_feed_id` (`target_feed_id`) USING BTREE,
  KEY `IDX_ultary_ai_target_pet_id` (`target_pet_id`) USING BTREE,
  KEY `IDX_ultary_ai_feature_status` (`feature_type`,`status`) USING BTREE,
  KEY `IDX_ai_request_job` (`moderation_job_id`,`attempt_no`),
  CONSTRAINT `FK_ai_target_feed` FOREIGN KEY (`target_feed_id`) REFERENCES `ultary_feed` (`feed_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_ai_target_pet` FOREIGN KEY (`target_pet_id`) REFERENCES `ultary_pet` (`pet_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_ai_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1957 DEFAULT CHARSET=utf8mb4 COMMENT='AI 문구 추천, 해시태그 추천, 프로필 소개, alt text 등 요청 이력';
/*!40101 SET character_set_client = @saved_cs_client */;

