DROP TABLE IF EXISTS `ultary_dm_room`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_dm_room` (
  `dm_room_id` int(11) NOT NULL AUTO_INCREMENT,
  `pair_key` varchar(32) NOT NULL COMMENT '두 사람 한 쌍',
  `user_low` int(11) NOT NULL,
  `user_high` int(11) NOT NULL,
  `low_last_read_message_id` int(11) DEFAULT NULL,
  `high_last_read_message_id` int(11) DEFAULT NULL,
  `low_left_at` datetime DEFAULT NULL,
  `high_left_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`dm_room_id`) USING BTREE,
  UNIQUE KEY `UK_ultary_dm_room_pair_key` (`pair_key`) USING BTREE,
  KEY `IDX_ultary_dm_room_user_low` (`user_low`) USING BTREE,
  KEY `IDX_ultary_dm_room_user_high` (`user_high`) USING BTREE,
  CONSTRAINT `FK_dm_room_user_high` FOREIGN KEY (`user_high`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE,
  CONSTRAINT `FK_dm_room_user_low` FOREIGN KEY (`user_low`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=478 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

