DROP TABLE IF EXISTS `ultary_feed`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_feed` (
  `feed_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_no` int(11) NOT NULL COMMENT '피드 작성자',
  `content` varchar(500) DEFAULT NULL COMMENT '본문. 해시태그 텍스트 포함 최대 500자',
  `visibility` enum('PUBLIC','NEIGHBORS','PRIVATE') NOT NULL DEFAULT 'PUBLIC' COMMENT 'PUBLIC all, NEIGHBORS accepted follow, PRIVATE owner',
  `allow_comment` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1이면 댓글·답글 허용. 끄면 작성자만 가능',
  `like_count` int(11) NOT NULL DEFAULT '0',
  `comment_count` int(11) NOT NULL DEFAULT '0',
  `pin_count` int(11) NOT NULL DEFAULT '0' COMMENT '울타리에 고정한 사람 수',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by_user_no` int(11) DEFAULT NULL COMMENT '실제 삭제한 사용자 (작성자 또는 COLLABORATOR 펫 보호자)',
  PRIMARY KEY (`feed_id`) USING BTREE,
  KEY `IDX_ultary_feed_user_created` (`user_no`,`created_at`) USING BTREE,
  KEY `IDX_ultary_feed_visibility_created` (`visibility`,`created_at`) USING BTREE,
  KEY `IDX_ultary_feed_is_deleted_created` (`is_deleted`,`created_at`) USING BTREE,
  KEY `IDX_ultary_feed_deleted_by_user_no` (`deleted_by_user_no`) USING BTREE,
  CONSTRAINT `FK_feed_deleted_by_user` FOREIGN KEY (`deleted_by_user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_feed_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3740 DEFAULT CHARSET=utf8mb4 COMMENT='반려동물 일상 피드';
/*!40101 SET character_set_client = @saved_cs_client */;

