INSERT INTO `ultary_feed` VALUES (101,101,'코코와 초록 잔디를 걸었어요. 새로운 냄새가 가득한 오늘의 산책.. #산책 #강아지산책','PUBLIC',1,19,27,4,'2026-08-07 03:22:30','2026-08-07 03:22:30',0,NULL,NULL),(102,102,'호두의 커다란 하품! 잠에서 막 깬 표정도 귀여워서 남겨요. #고양이 #휴식 #귀여움 #힐링 #하품','PUBLIC',1,20,17,1,'2026-08-10 18:38:28','2026-08-10 18:38:28',0,NULL,NULL),(103,103,'구름이와 집에서 보내는 포근한 하루. 폭신한 담요 위가 제일 좋은가 봐요. #집콕 #휴식 #말티즈 #힐링','PUBLIC',1,24,27,1,'2026-08-11 09:06:09','2026-08-11 09:06:09',0,NULL,NULL),(105,101,'코코와 레오가 함께한 피크닉. 잔디 위에 나란히 앉아 쉬어 가는 우리 집 두 친구. #피크닉 #강아지산책 #산책코스 #주말산책 #나들이','PUBLIC',1,13,13,3,'2026-09-01 18:22:30','2026-09-01 18:22:30',0,NULL,NULL),(107,102,'보리의 웃는 얼굴을 담았어요. 햇살 좋은 날의 기분 좋은 산책. #피크닉 #산책 #펫스타그램 #반려견 #반려견일상','PUBLIC',1,10,8,0,'2026-08-30 06:02:28','2026-08-30 06:02:28',0,NULL,NULL),(110,104,'마루와 호두가 나란히 앉았어요. 함께 보내는 오후가 더 즐거워요. #견생샷 #반려인소통 #합사 #친구','PUBLIC',1,10,21,0,'2026-08-04 01:01:38','2026-08-04 01:01:38',0,NULL,NULL),(111,104,'노을빛 산책길에서 만난 마루의 환한 표정. 내일도 같이 걷자. #강아지산책 #저녁산책 #시바견','PUBLIC',1,7,5,0,'2026-08-14 01:07:48','2026-08-14 01:07:48',0,NULL,NULL),(112,105,'호수 앞에서 쉬어 가는 라떼. 푸른 풍경과 함께 오래 기억하고 싶은 하루.','PUBLIC',1,10,23,0,'2026-10-07 10:51:44','2026-10-29 10:22:44',0,NULL,NULL),(113,105,'노을 아래 루비와 함께한 산책. 오늘의 마지막 햇살까지 즐겼어요.','PUBLIC',1,9,8,0,'2026-10-07 12:51:44','2026-10-29 10:22:44',0,NULL,NULL),(114,101,'몽이와 반려동물 동반 카페에 들렀어요. 보호자 간식 옆에서 얌전히 기다리는 중! #펫카페 #강아지동반 #반려동물동반카페','NEIGHBORS',1,8,17,0,'2026-09-12 15:45:00','2026-09-12 15:45:00',0,NULL,NULL),(118,102,'창가 소파에서 느긋하게 쉬는 레오. 부드러운 담요와 햇살이면 충분해요. #고양이 #펫스타그램 #펫쿠션','PUBLIC',1,9,20,0,'2026-09-20 17:47:35','2026-09-20 17:47:35',0,NULL,NULL),(122,103,'모카의 창가 자리에서 시작하는 느긋한 오후. 햇살을 실컷 즐겼어요. #고양이 #일상기록','PUBLIC',1,10,8,0,'2026-09-20 09:30:49','2026-09-20 09:30:49',0,NULL,NULL),(129,6131,'[광고] 베이지 체크 데일리 하네스 & 리드줄 세트. 차분한 체크 패턴으로 매일의 산책을 준비하세요. #체크하네스','PUBLIC',1,9,4,0,'2026-10-14 07:05:51','2026-10-29 10:25:42',0,NULL,NULL),(130,6131,'[광고·데모 이벤트] 우리 아이 산책 사진에 #산책하네스 태그를 달아 올려주세요! 참여자 중 추첨을 통해 하네스를 드립니다.','PUBLIC',1,10,13,1,'2026-10-14 05:05:51','2026-10-29 10:25:42',0,NULL,NULL),(132,6132,'[광고] 데일리 케어 펫 샴푸 & 슬리커 브러시 세트. 샴푸와 브러시로 일상 털 관리를 간편하게 준비하세요. #그루밍세트','PUBLIC',1,8,10,0,'2026-10-14 01:05:51','2026-10-29 10:25:42',0,NULL,NULL),(133,6132,'[광고] 내추럴 로프 터그 & 러버 본 토이 세트. 당기고 씹으며 즐기는 놀이 시간을 준비하세요. #강아지장난감','PUBLIC',1,9,7,0,'2026-10-13 23:05:51','2026-10-29 10:25:42',0,NULL,NULL),(135,6132,'[광고·데모 이벤트] 간식을 기다리는 귀여운 순간을 #강아지간식 태그와 함께 공유해주세요. 추첨을 통해 미니 본 트릿을 드립니다!','PUBLIC',1,9,4,0,'2026-10-13 19:05:51','2026-10-29 10:25:42',0,NULL,NULL),(136,6132,'[광고] 포우프린트 세라믹 볼 & 실리콘 매트 세트. 식기와 매트로 식사 공간을 깔끔하게 꾸며 보세요. #강아지식기','PUBLIC',1,6,2,0,'2026-10-13 17:05:51','2026-10-29 10:25:42',0,NULL,NULL),(139,6133,'[광고] 마일드 앤 세이프 데일리 펫 샴푸 500ml. 편리한 펌프 용기로 매일의 목욕 준비를 간편하게. #펫샴푸','PUBLIC',1,9,3,0,'2026-10-13 11:05:51','2026-10-29 10:25:42',0,NULL,NULL),(141,6133,'[광고] 소프트핀 데일리 슬리커 펫 브러시. 편안한 손잡이로 반려동물의 털을 차분히 정돈하세요. #펫브러시','PUBLIC',1,9,9,0,'2026-10-13 07:05:51','2026-10-29 10:25:42',0,NULL,NULL),(142,6129,'[광고] 내추럴 우드 더블 세라믹 펫 다이닝 테이블. 사료와 물을 한 공간에 담아 깔끔하게 준비하세요. #원목식기','PUBLIC',1,9,6,0,'2026-10-13 05:05:51','2026-10-29 10:25:42',0,NULL,NULL),(143,104,'가벼운 발걸음으로 동네를 걷는 마루. 익숙한 길도 매일 새로워요. #산책 #일상기록 #시바견 #시바이누 #산책길 #동네산책 #강아지산책','PUBLIC',1,8,7,0,'2026-09-01 17:19:18','2026-09-01 17:19:18',0,NULL,NULL),(144,6129,'[광고] 세이지 그린 펫 데일리 라이프 스타터 세트. 산책과 놀이, 간식 시간을 한 번에 준비하세요. #산책세트','PUBLIC',1,10,9,0,'2026-10-13 01:05:51','2026-10-29 10:25:42',0,NULL,NULL),(147,6129,'[광고] 내추럴 펫 플레이 & 트릿 홈 세트. 놀이와 간식 시간을 함께 준비하는 실용적인 구성입니다. #놀이간식세트','PUBLIC',1,6,6,0,'2026-10-12 19:05:51','2026-10-29 10:25:42',0,NULL,NULL),(149,104,'별이의 신나는 집 안 탐험. 작은 장난감 하나에도 눈이 반짝여요. #반려묘 #실내놀이 #고양이 #집사일상','PUBLIC',1,7,4,0,'2026-08-22 01:12:44','2026-08-22 01:12:44',0,NULL,NULL),(152,103,'담요 속에 쏙 들어간 단추. 오늘은 집에서 푹 쉬는 날이에요. #휴식 #힐링 #집콕 #강아지 #일상기록','PUBLIC',1,6,3,0,'2026-08-31 09:18:29','2026-08-31 09:18:29',0,NULL,NULL),(154,6130,'[광고] 클라우드 보아 포근 원형 펫 베드. 포근하게 쉴 수 있는 우리 아이의 자리를 만들어 주세요. #펫쿠션','PUBLIC',1,5,7,0,'2026-10-12 05:05:51','2026-10-29 10:25:42',0,NULL,NULL),(2748,104,'꽃 옆에서 조용히 구경하는 까망이. 호기심 가득한 눈빛을 담았어요. #코숏 #반려묘 #일상기록 #고양이 #검은고양이','PUBLIC',1,3,4,0,'2026-09-09 01:23:50','2026-09-09 01:23:50',0,NULL,NULL),(2749,208,'초코가 아끼는 인형과 보내는 오후. 같이 뒹굴다 보니 시간이 훌쩍 갔네요. #닥스훈트 #강아지일상 #뒹굴뒹굴 #애착인형','PUBLIC',1,4,3,0,'2026-10-29 10:22:43','2026-11-03 10:00:52',0,NULL,NULL),(2750,208,'밤비와 집에서 장난감 놀이. 편안한 옷을 입고 느긋하게 쉬는 중이에요. #휴식 #닥스훈트 #실내놀이 #멍스타그램','PUBLIC',1,5,5,0,'2026-10-29 10:22:43','2026-11-03 09:58:56',0,NULL,NULL),(2751,209,'햇살 드는 소파에서 잠든 치즈. 조용한 낮잠 시간을 살짝 기록해요. #코숏 #고양이 #일상기록 #힐링 #휴식','PUBLIC',1,6,3,0,'2026-10-29 10:22:43','2026-11-03 09:58:07',0,NULL,NULL),(2752,209,'낙엽 사이를 킁킁 살피는 쿠키. 가을 산책에는 구경할 게 참 많아요. #나들이 #킁킁 #산책 #강아지산책 #비글','PUBLIC',1,7,4,0,'2026-10-29 10:22:43','2026-11-03 09:57:06',0,NULL,NULL),(2754,6130,'[광고] 클리어 윈도우 에어홀 펫 백팩 캐리어. 통풍구와 투명 창을 갖춘 반려동물 이동가방입니다. #이동가방','PUBLIC',1,3,0,0,'2026-10-29 10:22:43','2026-10-29 10:25:42',0,NULL,NULL),(2755,6130,'[광고·데모 이벤트] 우리 아이의 신나는 놀이 사진에 #펫토이세트 태그를 달아주세요! 추첨을 통해 봉제·로프 토이 세트를 드립니다.','PUBLIC',1,4,4,0,'2026-10-29 10:22:43','2026-10-29 10:25:42',0,NULL,NULL),(2756,104,'마루의 식사 자리에 새 식기를 놓았어요. 밥과 물을 나란히 준비하니 한결 깔끔해졌네요. #원목식기 #시바견 #강아지식사 #강아지용품 #시바이누','PUBLIC',1,5,6,0,'2026-10-17 01:47:15','2026-10-17 01:47:15',0,NULL,NULL),(2757,209,'쿠키의 밥 먹는 시간. 식사 공간을 한곳에 정리하고 오늘도 천천히 맛있게 먹어요. #원목식기 #반려견 #반려동물 #강아지용품 #강아지식기 #먹방','PUBLIC',1,6,1,0,'2026-10-29 10:54:20','2026-11-02 17:36:14',0,NULL,NULL),(2758,105,'루비와 라떼의 산책 준비! 새 하네스를 입고 각자의 속도로 걸었어요. 두 친구의 산책 기록을 모아봅니다. #산책하네스','PUBLIC',1,4,0,0,'2026-10-29 10:54:20','2026-10-29 10:54:20',0,NULL,NULL),(2759,208,'밤비와 집에서 보내는 놀이 시간. 물고 당기며 놀다 보니 지루할 틈이 없네요. #강아지장난감 #놀이 #터그놀이 #반려견 #펫토이','PUBLIC',1,8,4,0,'2026-10-29 10:54:20','2026-11-02 17:33:05',0,NULL,NULL),(2760,104,'별이가 새 장난감을 탐색하는 중이에요. 강아지용 장난감에도 호기심을 보이네요. 옆에서 지켜보며 잠깐 놀았어요. #강아지장난감 #고양이 #놀이 #반려묘 #펫토이','PUBLIC',1,3,5,0,'2026-10-06 09:40:41','2026-10-06 09:40:41',0,NULL,NULL),(2761,104,'까망이와 함께하는 짧은 빗질 시간. 편안해하는 만큼만 조금씩 털을 정돈했어요. #펫브러시 #빗질 #털관리 #털갈이 #털정리','PUBLIC',1,4,5,0,'2026-09-29 01:36:09','2026-09-29 01:36:09',0,NULL,NULL),(2762,209,'치즈의 오늘 그루밍 기록. 느긋하게 쉬는 동안 살살 빗겨 주니 포근한 털이 한결 가지런해졌어요. #펫브러시 #그루밍 #털관리','PUBLIC',1,5,5,0,'2026-10-29 10:54:20','2026-11-03 15:37:55',0,NULL,NULL),(2763,208,'초코의 일상용품을 모아봤어요. 식사 자리에는 새 식기를, 목욕 준비에는 샴푸를 챙겼습니다. #강아지식기 #펫샴푸 #펫용품 #목욕 #강아지용품','PUBLIC',1,6,5,0,'2026-10-29 10:54:20','2026-11-02 17:29:53',0,NULL,NULL),(2764,104,'마루와 모카가 함께한 하루. 식사와 산책 준비를 하며 두 친구의 모습을 한 장에 담았어요. #원목식기 #산책하네스 #반려동물 #산책준비','PUBLIC',1,7,7,0,'2026-09-19 17:30:24','2026-09-19 17:30:24',0,NULL,NULL),(3707,101,'우리 집 삼총사 소개 🐾\n\n햇살 좋아하는 코코,\n카페만 가면 신나는 몽이,\n창가 자리가 제일 좋은 레오.\n\n좋아하는 것도 성격도 다 다르지만\n함께라서 더 즐거운 우리 집 일상 🤍\n\n#코코 #몽이 #레오 #반려동물 #멍스타그램 #냥스타그램 #펫스타그램 #울타리','PUBLIC',1,6,6,0,'2026-08-18 16:07:30','2026-08-18 16:07:30',0,NULL,NULL),(3708,101,'둘이 붙어 있으면 케미가 두 배 🐶🐱\n\n코코와 레오는 여유로운 피크닉 친구,\n코코와 몽이는 어디서든 신나는 산책 친구!\n\n조합마다 분위기는 달라도\n같이 있는 순간은 언제나 귀엽다 🌿\n\n#반려동물친구 #코코 #몽이 #레오 #강아지와고양이 #펫일상 #산책스타그램 #울타리','PUBLIC',1,4,4,0,'2026-09-25 11:15:00','2026-09-25 11:15:00',0,NULL,NULL),(3709,101,'결국 셋이 다 모여야 우리 집 완전체 🐾\n\n몽이랑 레오의 포근한 오후부터\n코코까지 합류한 호숫가 피크닉,\n집에서 나란히 쉬는 순간까지.\n\n특별한 일이 없어도\n함께 있으면 그게 제일 좋은 하루 ☀️\n\n#우리집삼총사 #코코 #몽이 #레오 #반려동물일상 #댕냥이 #펫라이프 #일상기록 #울타리','PUBLIC',1,5,5,0,'2026-10-06 08:37:30','2026-10-06 08:37:30',0,NULL,101),(3722,101,'코코랑 까망이, 처음엔 어색하더니 어느새 이렇게 붙어있기 🐶🐱 햇살 좋은 날엔 같이 늘어지는 게 최고!\n\n#코코 #까망이 #댕냥친구 #반려동물일상 #펫스타그램 #울타리','PUBLIC',1,7,7,0,'2026-10-20 10:52:30','2026-10-20 10:52:30',0,NULL,NULL),(3723,102,'몽이랑 보리랑 호숫가 피크닉 🌼 간식도 먹고 바람도 쐬고, 신나게 놀다 온 하루!\n\n#몽이 #보리 #강아지친구 #피크닉 #산책일상 #멍스타그램 #울타리','PUBLIC',1,8,8,0,'2026-10-28 08:21:31','2026-10-28 08:21:31',0,NULL,NULL),(3724,103,'오늘은 레오랑 단추의 휴식 시간. 나란히 누워있는 모습이 생각보다 너무 잘 어울린다 🤎\n\n#레오 #단추 #댕냥이 #포근한하루 #반려동물 #일상기록 #울타리','PUBLIC',1,9,9,0,'2026-10-27 17:53:50','2026-10-27 17:53:50',0,NULL,NULL),(3725,104,'산책하다 만난 보리까지 합류! 마루랑 별이도 오늘 새로운 친구가 생겼어요 🌿🐾\n\n#마루 #별이 #보리 #반려동물친구 #산책 #펫일상 #울타리','PUBLIC',1,10,10,0,'2026-11-04 01:58:21','2026-11-06 11:15:22',0,NULL,NULL),(3726,103,'햇살 좋은 창가에서 만난 까망이와 구름 ☀️ 성격은 달라도 같이 있으면 제법 평화로운 조합.\n\n#까망이 #구름 #댕냥친구 #햇살맛집 #반려동물일상 #울타리','PUBLIC',1,5,5,0,'2026-10-07 17:41:30','2026-10-07 17:41:30',0,NULL,NULL),(3727,102,'보리 친구들 놀러 온 날! 모카랑 단추까지 모이니 집이 금세 북적북적 🐾 그래도 이런 북적임은 언제든 환영!\n\n#보리 #모카 #단추 #우리집놀이터 #반려동물친구 #펫라이프 #울타리','PUBLIC',1,6,6,0,'2026-10-08 20:57:31','2026-10-08 20:57:31',0,NULL,NULL),(3728,104,'별이랑 호두의 카페 나들이에 코코도 합류 ☕🐾 셋이 같이 있으니 사진 한 장도 그냥 지나칠 수가 없다.\n\n#코코 #별이 #호두 #펫카페 #댕냥이 #친구스타그램 #울타리','PUBLIC',1,7,7,0,'2026-10-25 01:52:11','2026-10-25 01:52:11',0,NULL,NULL),(3729,101,'몽이, 구름, 모카랑 꽃구경 🌸 날씨도 좋고 친구들도 함께라 더 기분 좋은 하루!\n\n#몽이 #구름 #모카 #꽃구경 #반려동물친구 #펫일상 #울타리','PUBLIC',1,8,8,0,'2026-10-31 23:37:30','2026-11-06 15:09:33',0,NULL,NULL);
/*!40000 ALTER TABLE `ultary_feed` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `ultary_feed_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_feed_comment` (
  `feed_comment_id` int(11) NOT NULL AUTO_INCREMENT,
  `feed_id` int(11) NOT NULL,
  `user_no` int(11) NOT NULL,
  `content` varchar(100) NOT NULL,
  `like_count` int(11) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`feed_comment_id`) USING BTREE,
  KEY `IDX_ultary_feed_comment_feed_created` (`feed_id`,`created_at`) USING BTREE,
  KEY `IDX_ultary_feed_comment_user_no` (`user_no`) USING BTREE,
  CONSTRAINT `FK_feed_comment_feed` FOREIGN KEY (`feed_id`) REFERENCES `ultary_feed` (`feed_id`) ON UPDATE CASCADE,
  CONSTRAINT `FK_feed_comment_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2461 DEFAULT CHARSET=utf8mb4 COMMENT='피드 댓글';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ultary_feed_comment` WRITE;
