DROP TABLE IF EXISTS `ultary_file`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_file` (
  `file_id` int(11) NOT NULL AUTO_INCREMENT,
  `original_name` varchar(100) DEFAULT NULL COMMENT '업로드 당시 원본 파일명',
  `store_name` varchar(100) NOT NULL COMMENT '서버에 저장된 파일명',
  `extension` varchar(10) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size` int(11) DEFAULT NULL COMMENT 'byte 단위 파일 크기',
  `file_path` varchar(300) NOT NULL,
  `source_type` varchar(20) DEFAULT NULL COMMENT 'OWNED|UNSPLASH|AI|ETC',
  `author_name` varchar(100) DEFAULT NULL COMMENT 'author',
  `source_url` varchar(500) DEFAULT NULL COMMENT 'source page',
  `license_url` varchar(500) DEFAULT NULL COMMENT 'license page',
  `copyright_notice` varchar(255) DEFAULT NULL COMMENT 'notice',
  `uploaded_by_user_no` int(11) DEFAULT NULL,
  `uploaded_by_admin_no` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`file_id`) USING BTREE,
  KEY `IDX_ultary_file_uploaded_by_user_no` (`uploaded_by_user_no`) USING BTREE,
  KEY `IDX_ultary_file_uploaded_by_admin_no` (`uploaded_by_admin_no`) USING BTREE,
  KEY `IDX_ultary_file_is_deleted` (`is_deleted`) USING BTREE,
  KEY `IDX_ultary_file_source_type` (`source_type`),
  CONSTRAINT `FK_file_uploaded_admin` FOREIGN KEY (`uploaded_by_admin_no`) REFERENCES `ultary_admin` (`admin_no`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_file_uploaded_user` FOREIGN KEY (`uploaded_by_user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1996 DEFAULT CHARSET=utf8 COMMENT='이미지 및 첨부파일 메타데이터';
/*!40101 SET character_set_client = @saved_cs_client */;

