/*!40000 ALTER TABLE `ultary_file` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `ultary_neighbor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_neighbor` (
  `neighbor_id` int(11) NOT NULL AUTO_INCREMENT,
  `requester_user_no` int(11) NOT NULL COMMENT 'follow requester',
  `receiver_user_no` int(11) NOT NULL COMMENT 'follow receiver',
  `pair_key` varchar(50) NOT NULL COMMENT '역방향 중복 방지용 키. 작은 user_no:큰 user_no 형식',
  `status` enum('PENDING','ACCEPTED','REJECTED','BLOCKED') NOT NULL DEFAULT 'PENDING',
  `followed_back` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = receiver also follows requester',
  `followed_back_at` datetime DEFAULT NULL COMMENT 'follow-back time',
  `requested_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `accepted_at` datetime DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `blocked_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`neighbor_id`) USING BTREE,
  UNIQUE KEY `UK_ultary_neighbor_pair_key` (`pair_key`) USING BTREE,
  UNIQUE KEY `UK_ultary_neighbor_req_recv` (`requester_user_no`,`receiver_user_no`) USING BTREE,
  KEY `IDX_ultary_neighbor_receiver_status` (`receiver_user_no`,`status`) USING BTREE,
  KEY `IDX_ultary_neighbor_status` (`status`) USING BTREE,
  CONSTRAINT `FK_neighbor_receiver` FOREIGN KEY (`receiver_user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE,
  CONSTRAINT `FK_neighbor_requester` FOREIGN KEY (`requester_user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1481 DEFAULT CHARSET=utf8 COMMENT='follow relation. requester follows receiver. followed_back is mutual';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ultary_neighbor` WRITE;
/*!40000 ALTER TABLE `ultary_neighbor` DISABLE KEYS */;
