DROP TABLE IF EXISTS `ultary_notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_notification` (
  `notification_id` int(11) NOT NULL AUTO_INCREMENT,
  `receiver_user_no` int(11) NOT NULL COMMENT '알림을 받는 사용자',
  `actor_user_no` int(11) DEFAULT NULL COMMENT '알림을 발생시킨 사용자. 시스템 알림이면 null 가능',
  `type` enum('NEIGHBOR_REQUEST','FEED_LIKE','COMMENT_LIKE','REPLY_LIKE','FEED_COMMENT','COMMENT_MENTION','REPLY_MENTION','FEED_TAG','STORY_TAG','STORY_LIKE','AI_MODERATION','TAG_PROFILE_APPROVED','TAG_PROFILE_REJECTED') NOT NULL,
  `feed_id` int(11) DEFAULT NULL,
  `feed_pet_id` int(11) DEFAULT NULL,
  `feed_comment_id` int(11) DEFAULT NULL,
  `feed_reply_id` int(11) DEFAULT NULL,
  `story_id` int(11) DEFAULT NULL,
  `neighbor_id` int(11) DEFAULT NULL,
  `content` varchar(80) DEFAULT NULL COMMENT '인용 텍스트 일부. 댓글·답글 통합은 최신 글로 덮어씀',
  `actor_count` int(11) NOT NULL DEFAULT '1',
  `has_comment` tinyint(1) NOT NULL DEFAULT '0',
  `has_reply` tinyint(1) NOT NULL DEFAULT '0',
  `group_key` varchar(80) NOT NULL,
  `is_read` tinyint(1) NOT NULL DEFAULT '0',
  `read_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`notification_id`) USING BTREE,
  UNIQUE KEY `UK_ultary_notification_receiver_group` (`receiver_user_no`,`group_key`),
  KEY `IDX_ultary_notification_receiver_read` (`receiver_user_no`,`is_read`,`created_at`) USING BTREE,
  KEY `IDX_ultary_notification_actor_user_no` (`actor_user_no`) USING BTREE,
  KEY `IDX_ultary_notification_feed_id` (`feed_id`) USING BTREE,
  KEY `IDX_ultary_notification_feed_pet_id` (`feed_pet_id`) USING BTREE,
  KEY `IDX_ultary_notification_comment_id` (`feed_comment_id`) USING BTREE,
  KEY `IDX_ultary_notification_reply_id` (`feed_reply_id`) USING BTREE,
  KEY `IDX_ultary_notification_neighbor_id` (`neighbor_id`) USING BTREE,
  KEY `IDX_ultary_notification_receiver_updated` (`receiver_user_no`,`updated_at`),
  KEY `IDX_ultary_notification_story_id` (`story_id`),
  CONSTRAINT `FK_notification_actor` FOREIGN KEY (`actor_user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_comment` FOREIGN KEY (`feed_comment_id`) REFERENCES `ultary_feed_comment` (`feed_comment_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_feed` FOREIGN KEY (`feed_id`) REFERENCES `ultary_feed` (`feed_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_feed_pet` FOREIGN KEY (`feed_pet_id`) REFERENCES `ultary_feed_pet` (`feed_pet_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_neighbor` FOREIGN KEY (`neighbor_id`) REFERENCES `ultary_neighbor` (`neighbor_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_receiver` FOREIGN KEY (`receiver_user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_reply` FOREIGN KEY (`feed_reply_id`) REFERENCES `ultary_feed_reply` (`feed_reply_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_notification_story` FOREIGN KEY (`story_id`) REFERENCES `ultary_story` (`story_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4152 DEFAULT CHARSET=utf8mb4 COMMENT='follow request, likes, comments, mentions, tags, story likes';
/*!40101 SET character_set_client = @saved_cs_client */;

