DROP TABLE IF EXISTS `ultary_notification_setting`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_notification_setting` (
  `user_no` int(11) NOT NULL,
  `neighbor` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'follow request alerts',
  `like_post` tinyint(1) NOT NULL DEFAULT '1',
  `like_comment` tinyint(1) NOT NULL DEFAULT '1',
  `like_reply` tinyint(1) NOT NULL DEFAULT '1',
  `comment_on_post` tinyint(1) NOT NULL DEFAULT '1',
  `reply_on_comment` tinyint(1) NOT NULL DEFAULT '1',
  `mention` tinyint(1) NOT NULL DEFAULT '1',
  `tag_post` tinyint(1) NOT NULL DEFAULT '1',
  `tag_story` tinyint(1) NOT NULL DEFAULT '1',
  `story_react` tinyint(1) NOT NULL DEFAULT '1',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_no`),
  CONSTRAINT `FK_notification_setting_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

