CREATE TABLE `ultary_report` (
  `report_id` int(11) NOT NULL AUTO_INCREMENT,
  `reporter_user_no` int(11) NOT NULL,
  `target_type` enum('USER','FEED','COMMENT','REPLY') NOT NULL,
  `target_user_no` int(11) DEFAULT NULL,
  `target_feed_id` int(11) DEFAULT NULL,
  `target_comment_id` int(11) DEFAULT NULL,
  `target_reply_id` int(11) DEFAULT NULL,
  `reason` enum('SPAM','ABUSE','HARASSMENT','SEXUAL','VIOLENCE','HATE','IMPERSONATION','PRIVACY','OTHER') NOT NULL COMMENT 'SPAM ABUSE HARASSMENT SEXUAL VIOLENCE HATE IMPERSONATION PRIVACY OTHER',
  `status` enum('REQUESTED','CONFIRMED','DELETED','REJECTED','SUSPENDED') NOT NULL DEFAULT 'REQUESTED' COMMENT 'REQUESTED 신고요청, CONFIRMED 확인, DELETED 삭제조치, REJECTED 거절, SUSPENDED 정지',
  `admin_no` int(11) DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`report_id`) USING BTREE,
  KEY `IDX_ultary_report_reporter_user_no` (`reporter_user_no`) USING BTREE,
  KEY `IDX_ultary_report_target_user_no` (`target_user_no`) USING BTREE,
  KEY `IDX_ultary_report_target_feed_id` (`target_feed_id`) USING BTREE,
  KEY `IDX_ultary_report_target_comment_id` (`target_comment_id`) USING BTREE,
  KEY `IDX_ultary_report_target_reply_id` (`target_reply_id`) USING BTREE,
  KEY `IDX_ultary_report_admin_no` (`admin_no`) USING BTREE,
  KEY `IDX_ultary_report_status_created` (`status`,`created_at`) USING BTREE,
  CONSTRAINT `FK_report_admin` FOREIGN KEY (`admin_no`) REFERENCES `ultary_admin` (`admin_no`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_report_reporter` FOREIGN KEY (`reporter_user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE,
  CONSTRAINT `FK_report_target_comment` FOREIGN KEY (`target_comment_id`) REFERENCES `ultary_feed_comment` (`feed_comment_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_report_target_feed` FOREIGN KEY (`target_feed_id`) REFERENCES `ultary_feed` (`feed_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_report_target_reply` FOREIGN KEY (`target_reply_id`) REFERENCES `ultary_feed_reply` (`feed_reply_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_report_target_user` FOREIGN KEY (`target_user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=648 DEFAULT CHARSET=utf8 COMMENT='사용자 신고 및 관리자 처리 이력';
/*!40101 SET character_set_client = @saved_cs_client */;

