CREATE TABLE `ultary_story` (
  `story_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_no` int(11) NOT NULL COMMENT '스토리 작성자',
  `file_id` int(11) NOT NULL COMMENT '원본 미디어 (이미지 또는 짧은 영상)',
  `media_type` enum('IMAGE','VIDEO') NOT NULL,
  `thumbnail_file_id` int(11) DEFAULT NULL COMMENT 'VIDEO 커버. IMAGE면 NULL',
  `duration_sec` int(11) DEFAULT NULL COMMENT 'VIDEO 재생 초(최대 60). IMAGE면 NULL',
  `caption` varchar(200) DEFAULT NULL COMMENT '짧은 문구',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '업로드 시각 (UI 표시)',
  `expires_at` datetime NOT NULL COMMENT 'created_at + 24시간. 이후 비활성',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`story_id`) USING BTREE,
  KEY `IDX_ultary_story_user_expires` (`user_no`,`expires_at`) USING BTREE,
  KEY `IDX_ultary_story_expires_deleted` (`expires_at`,`is_deleted`) USING BTREE,
  KEY `IDX_ultary_story_file_id` (`file_id`) USING BTREE,
  KEY `IDX_ultary_story_thumbnail_file_id` (`thumbnail_file_id`) USING BTREE,
  CONSTRAINT `FK_story_file` FOREIGN KEY (`file_id`) REFERENCES `ultary_file` (`file_id`) ON UPDATE CASCADE,
  CONSTRAINT `FK_story_thumbnail_file` FOREIGN KEY (`thumbnail_file_id`) REFERENCES `ultary_file` (`file_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_story_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=736 DEFAULT CHARSET=utf8mb4 COMMENT='24시간 스토리 (사진/짧은 영상)';
