CREATE TABLE `ultary_tag` (
  `tag_id` int(11) NOT NULL AUTO_INCREMENT,
  `hashtag` varchar(30) NOT NULL COMMENT '# 뒤에 쓰는 키. 중복 허용 (검색 후 선택). 생성 후 변경 불가',
  `purpose` enum('USER','COMMERCIAL') NOT NULL DEFAULT 'USER' COMMENT 'USER casual hashtag, COMMERCIAL product tag',
  `profile_status` enum('NONE','PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'NONE' COMMENT 'APPROVED shows title, content, link, images',
  `title` varchar(100) DEFAULT NULL COMMENT '상품명/소개 제목 (길 수 있음). 단순 해시태그는 NULL',
  `handle` varchar(30) DEFAULT NULL COMMENT '선택 고유 코드. hashtag 중복 시 구분. 영문·숫자·_ , UNIQUE',
  `handle_changed_at` datetime DEFAULT NULL COMMENT 'handle 최초 설정/마지막 변경 시각. NULL=handle 미설정(최초 설정 자유). 설정·변경 후 30일간 재변경 불가. 생성 시 handle을 넣으면 생성 시각으로 설정',
  `content` varchar(500) DEFAULT NULL COMMENT '태그 소개글',
  `link` varchar(200) DEFAULT NULL COMMENT '상품/외부 링크',
  `use_count` int(11) NOT NULL DEFAULT '0',
  `created_by_user_no` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`tag_id`) USING BTREE,
  UNIQUE KEY `UK_ultary_tag_handle` (`handle`) USING BTREE,
  KEY `IDX_ultary_tag_hashtag` (`hashtag`) USING BTREE,
  KEY `IDX_ultary_tag_created_by_user_no` (`created_by_user_no`) USING BTREE,
  KEY `IDX_ultary_tag_is_deleted` (`is_deleted`) USING BTREE,
  CONSTRAINT `FK_tag_user` FOREIGN KEY (`created_by_user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1487 DEFAULT CHARSET=utf8mb4 COMMENT='해시태그/상품·소개 태그 (#hashtag 불변, 선택 handle)';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ultary_tag` WRITE;
/*!40000 ALTER TABLE `ultary_tag` DISABLE KEYS */;
