DROP TABLE IF EXISTS `ultary_token`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_token` (
  `token_id` int(11) NOT NULL AUTO_INCREMENT,
  `owner_type` enum('USER','ADMIN') NOT NULL COMMENT 'USER 또는 ADMIN',
  `user_no` int(11) DEFAULT NULL,
  `admin_no` int(11) DEFAULT NULL,
  `session_id` char(36) DEFAULT NULL,
  `logged_in_at` datetime DEFAULT NULL,
  `connect_ip` varchar(50) DEFAULT NULL,
  `connect_agent` varchar(200) DEFAULT NULL,
  `refresh_token` varchar(500) NOT NULL,
  `expires_at` datetime NOT NULL,
  `is_revoked` tinyint(1) NOT NULL DEFAULT '0' COMMENT '로그아웃/비밀번호 변경 등으로 토큰을 폐기했는지 여부',
  `revoked_at` datetime DEFAULT NULL,
  `replaced_by_token_id` int(11) DEFAULT NULL,
  `rotated_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`token_id`) USING BTREE,
  KEY `IDX_ultary_token_user_no` (`user_no`) USING BTREE,
  KEY `IDX_ultary_token_admin_no` (`admin_no`) USING BTREE,
  KEY `IDX_ultary_token_owner_type` (`owner_type`) USING BTREE,
  KEY `IDX_ultary_token_expires_at` (`expires_at`) USING BTREE,
  KEY `IDX_ultary_token_is_revoked` (`is_revoked`) USING BTREE,
  KEY `IDX_ultary_token_user_session` (`user_no`,`session_id`),
  KEY `IDX_ultary_token_admin_session` (`admin_no`,`session_id`),
  CONSTRAINT `FK_token_admin` FOREIGN KEY (`admin_no`) REFERENCES `ultary_admin` (`admin_no`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_token_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1647 DEFAULT CHARSET=utf8 COMMENT='사용자/관리자 로그인 유지용 refresh token';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ultary_token` WRITE;
/*!40000 ALTER TABLE `ultary_token` DISABLE KEYS */;
/*!40000 ALTER TABLE `ultary_token` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `ultary_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ultary_user` (
  `user_no` int(11) NOT NULL AUTO_INCREMENT,
  `password` varchar(200) DEFAULT NULL COMMENT 'BCrypt 해시. 소셜만 사용 시 NULL, 이후 설정 가능',
  `password_changed_at` datetime DEFAULT NULL COMMENT '?????? ?????????????????. ??????NULL. ????????? ???????NOW()',
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=????? ????????????? ???????. ??? ?????? ??????? ??0',
  `name` varchar(20) DEFAULT NULL,
  `nickname` varchar(30) NOT NULL COMMENT '표시 이름. 한글 2~5 / 영문 4~10 / 혼합은 한글1=2 가중치 합 4~10. 소셜 가입 시 google|kakao + 랜덤영문(총 10자)',
  `nickname_changed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '닉네임 마지막 변경(또는 최초 부여) 시각. 생성 직후부터 7일간 재변경 불가',
  `previous_nickname` varchar(30) DEFAULT NULL COMMENT '���� �г����±�. ���� �� ���� �� ����. nickname_changed_at ���� 7�ϰ� �ߺ��������̷�Ʈ���� ���',
  `is_default_nickname` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=자동 생성 닉네임(변경 유도 대상), 0=사용자가 직접 변경함',
  `email` varchar(50) DEFAULT NULL COMMENT '소셜에서 전달되거나 이후 등록. 비밀번호 로그인 식별자로 사용 가능',
  `phone` varchar(20) DEFAULT NULL COMMENT '본인인증 후 등록. 비밀번호 로그인 식별자로 사용 가능',
  `bio` varchar(300) DEFAULT NULL COMMENT '프로필 소개글',
  `region_sido` varchar(30) DEFAULT NULL COMMENT '동네 기반 기능용 시/도',
  `region_sigungu` varchar(30) DEFAULT NULL COMMENT '동네 기반 기능용 시/군/구',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `withdrawal_status` enum('ACTIVE','REQUESTED','WITHDRAWN','SUSPENDED') NOT NULL DEFAULT 'ACTIVE' COMMENT '회원 상태. SUSPENDED=관리자 정지',
  `withdrawal_completed_at` datetime DEFAULT NULL,
  `suspended_at` datetime DEFAULT NULL COMMENT '회원 정지 시각. 해제하면 NULL',
  PRIMARY KEY (`user_no`) USING BTREE,
  UNIQUE KEY `UK_ultary_user_nickname` (`nickname`) USING BTREE,
  KEY `IDX_ultary_user_is_default_nickname` (`is_default_nickname`) USING BTREE,
  KEY `IDX_ultary_user_withdrawal_status` (`withdrawal_status`) USING BTREE,
  KEY `IDX_ultary_user_email` (`email`),
  KEY `IDX_ultary_user_phone` (`phone`),
  KEY `IDX_ultary_user_previous_nickname` (`previous_nickname`)
) ENGINE=InnoDB AUTO_INCREMENT=7765 DEFAULT CHARSET=utf8mb4 COMMENT='사용자 계정 및 보호자 프로필';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ultary_user` WRITE;
