  `private_account` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 means public posts and stories need the viewer to follow',
  `feed_visibility` enum('PUBLIC','NEIGHBORS','PRIVATE') NOT NULL DEFAULT 'PUBLIC' COMMENT '새 게시글 기본 공개 범위',
  `story_visibility` enum('PUBLIC','NEIGHBORS','PRIVATE') NOT NULL DEFAULT 'NEIGHBORS' COMMENT 'story visibility',
