  CONSTRAINT `FK_user_privacy_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='공개 범위. 행이 없으면 기본값';
