  `user_no` int(11) NOT NULL COMMENT '검색 후 울타리에 들어간 사용자',
  `target_user_no` int(11) DEFAULT NULL COMMENT '들어간 울타리 주인. 태그 이력이면 NULL',
  `target_tag_id` int(11) DEFAULT NULL COMMENT '들어간 태그 피드. 울타리 이력이면 NULL',
  `searched_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '같은 울타리 재방문 시 갱신',
  PRIMARY KEY (`user_search_history_id`) USING BTREE,
  UNIQUE KEY `UK_ultary_user_search_user` (`user_no`,`target_user_no`),
  UNIQUE KEY `UK_ultary_user_search_tag` (`user_no`,`target_tag_id`),
  KEY `IDX_ultary_user_search_user_time` (`user_no`,`searched_at`) USING BTREE,
  KEY `IDX_ultary_user_search_target_user` (`target_user_no`) USING BTREE,
  KEY `IDX_ultary_user_search_target_tag` (`target_tag_id`),
  CONSTRAINT `FK_user_search_target_user` FOREIGN KEY (`target_user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_user_search_user` FOREIGN KEY (`user_no`) REFERENCES `ultary_user` (`user_no`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1958 DEFAULT CHARSET=utf8 COMMENT='검색에서 들어간 유저 울타리. 한 사람당 대상 유저 1행';
